import SwiftUI

struct SplitTextInformationView: View {
    var body: some View {
        VStack(alignment: .leading, spacing: 10) {
            LessonTextPanel(title: "Separate text into useful fields", text: "Choose a current Text source column. Other columns remain available. Keep source retains the original text beside the extracted values; new names must be unique across the complete output. Conversion uses explicit Text, Integer, Number or Boolean types. Boolean accepts exactly true/false; integer conversion is checked and numbers must be finite. Regex extraction stays in Formula.")
            LessonTextPanel(title: "Literal delimiters and quoting", text: "Delimiters contain 1–128 Unicode code points, including custom multi-character separators. A quoted field starts at the beginning of a token. Closing quotes must be followed by the separator or end of the source. Double quote escaping repeats the chosen quote; Escape character escapes the following code point inside or outside quotes; None uses no escape. Quote and escape each contain one Unicode code point. An active quote cannot occur in the delimiter; an active escape cannot equal the quote or occur in the delimiter. Invalid combinations, unterminated quotes and trailing escapes stop the run. Quoting removes wrappers; separators inside quoted fields are literal text.")
            LessonTextPanel(title: "Columns and Rows", text: "Columns follows the ordered output grid. Extra fields can stop, drop or join the parsed remaining values into the final field with the literal delimiter. Short input can fill missing, fill empty text or stop. Empty text remains different from missing. Rows repeats other columns once per parsed token. Dropping empty tokens retains the original 1-based token positions, so ordinals can have gaps. Missing source is preserved as one missing token at ordinal 1, or stops by policy. Rows changes the observation population and belongs before Partition or fitted preprocessing; existing partition/fitted inputs are refused. Use group-aware evaluation when repeated entities share information.")
            LessonTextPanel(title: "Fixed width", text: "Each field reads the original source; overlapping fields are allowed. Start is 1-based and Width is a length. Unicode code points count combining marks separately and differ from user-perceived characters. UTF-8 bytes measure encoded bytes: slicing through a multibyte code point is a conversion failure, never replacement-character decoding. A short record affects only incomplete fields. Optional trimming removes Unicode whitespace at the ends before conversion. Missing conversion follows the chosen policy; source missing is handled separately.")
            LessonTextPanel(title: "Captured output and limits", text: "Apply commits one undoable draft; Revert reloads saved settings. Run uses the applied configuration and captured upstream population. Columns and Fixed width retain row IDs and partition/fitted evidence. Rows qualifies IDs by original row and original token position. Extraction streams to bounded storage, checks cancellation, admits at most 128 output columns and five million cells, limits a source cell to 10 MB and total emitted text to 250 MB. These are resource limits, not a 100,000-row truncation. Preview observations do not prove that every source row succeeds.")
        }
    }
}
